mapper.sql:
SELECT 'person' AS record_type, pi.kind, pi.normalized_value, COUNT(*) AS collision_size, MAX(ic.rebuilt_at) AS rebuilt_at FROM person_identity pi JOIN identity_collision ic ON ic.workspace_id = pi.workspace_id AND ic.person_identity_id = pi.id JOIN person p ON p.workspace_id = pi.workspace_id AND p.id = pi.person_id WHERE pi.workspace_id = #{workspaceId} AND pi.superseded_at IS NULL
AND pi.kind = #{kind}
GROUP BY pi.kind, pi.normalized_value HAVING COUNT(*) >= 2

SELECT 'company' AS record_type, ci.kind, ci.normalized_value, COUNT(*) AS collision_size, MAX(ic.rebuilt_at) AS rebuilt_at FROM company_identity ci JOIN identity_collision ic ON ic.workspace_id = ci.workspace_id AND ic.company_identity_id = ci.id JOIN company c ON c.workspace_id = ci.workspace_id AND c.id = ci.company_id WHERE ci.workspace_id = #{workspaceId} AND ci.superseded_at IS NULL AND c.archived_at IS NULL
AND ci.kind = #{kind}
GROUP BY ci.kind, ci.normalized_value HAVING COUNT(*) >= 2

mapper.delete:
DELETE ic
FROM identity_collision ic
JOIN person_identity pi
  ON pi.workspace_id = ic.workspace_id
  AND pi.id = ic.person_identity_id
WHERE ic.workspace_id = #{workspaceId}
  AND pi.kind = #{kind}
  AND pi.normalized_value = #{normalizedValue}

mapper.insert:
INSERT INTO identity_collision (workspace_id, person_identity_id, rebuilt_at)
SELECT collision.workspace_id, collision.identity_id, #{rebuiltAt}
FROM (
  SELECT pi.workspace_id,
         pi.id AS identity_id,
         COUNT(*) OVER () AS collision_size
  FROM person_identity pi
  JOIN person p
    ON p.workspace_id = pi.workspace_id
    AND p.id = pi.person_id
  WHERE pi.workspace_id = #{workspaceId}
    AND pi.kind = #{kind}
    AND pi.normalized_value = #{normalizedValue}
    AND pi.superseded_at IS NULL
    AND p.suspended_at IS NULL
    AND p.provision_ceased_at IS NULL
) collision
WHERE collision.collision_size >= 2
ON DUPLICATE KEY UPDATE rebuilt_at = #{rebuiltAt}

