  AND ci.id = ic.company_identity_id
WHERE ic.workspace_id = #{workspaceId}
  AND ci.kind = #{kind}
  AND ci.normalized_value = #{normalizedValue}

mapper.insert:
INSERT INTO identity_collision (workspace_id, company_identity_id, rebuilt_at)
SELECT collision.workspace_id, collision.identity_id, #{rebuiltAt}
FROM (
  SELECT ci.workspace_id,
         ci.id AS identity_id,
         COUNT(*) OVER () AS collision_size
  FROM company_identity ci
  JOIN company c
    ON c.workspace_id = ci.workspace_id
    AND c.id = ci.company_id
  WHERE ci.workspace_id = #{workspaceId}
    AND ci.kind = #{kind}
    AND ci.normalized_value = #{normalizedValue}
    AND ci.superseded_at IS NULL
) collision
WHERE collision.collision_size >= 2
ON DUPLICATE KEY UPDATE rebuilt_at = #{rebuiltAt}

mapper.select:
SELECT COUNT(*)
FROM identity_collision
WHERE workspace_id = #{workspaceId}

WITH collision_groups AS (
UNION ALL
), collision_groups_with_sentinel AS ( SELECT record_type, kind, normalized_value, collision_size, rebuilt_at FROM collision_groups UNION ALL SELECT NULL, NULL, NULL, NULL, NULL ), numbered_collision_groups AS ( SELECT record_type, kind, normalized_value, collision_size, rebuilt_at, COUNT(record_type) OVER () AS total, ROW_NUMBER() OVER ( ORDER BY record_type IS NULL, record_type, kind, normalized_value ) AS page_ordinal FROM collision_groups_with_sentinel ) SELECT /*+ MAX_EXECUTION_TIME(3000) */ record_type, kind, normalized_value, collision_size, rebuilt_at, total, page_ordinal FROM numbered_collision_groups WHERE ( record_type IS NOT NULL AND page_ordinal > #{offset} AND page_ordinal <= #{offset} + #{limit} ) OR ( record_type IS NULL AND total <= #{offset} ) ORDER BY page_ordinal

SELECT record_type, kind, normalized_value, record_id, record_name FROM (
(SELECT 'person' AS record_type, pi.kind AS kind, pi.normalized_value AS normalized_value, pi.person_id AS record_id, p.name AS record_name FROM person_identity pi JOIN identity_collision ic ON ic.workspace_id = pi.workspace_id AND ic.person_identity_id = pi.id JOIN person p ON p.workspace_id = pi.workspace_id AND p.id = pi.person_id WHERE pi.workspace_id = #{workspaceId} AND pi.superseded_at IS NULL AND pi.kind = #{group.kind} AND pi.normalized_value = #{group.normalizedValue} AND pi.person_id > #{afterRecordId}
ORDER BY pi.person_id LIMIT #{memberLimit})
(SELECT 'company' AS record_type, ci.kind AS kind, ci.normalized_value AS normalized_value, ci.company_id AS record_id, c.name AS record_name FROM company_identity ci JOIN identity_collision ic ON ic.workspace_id = ci.workspace_id AND ic.company_identity_id = ci.id JOIN company c ON c.workspace_id = ci.workspace_id AND c.id = ci.company_id WHERE ci.workspace_id = #{workspaceId} AND ci.superseded_at IS NULL AND ci.kind = #{group.kind} AND ci.normalized_value = #{group.normalizedValue} AND ci.company_id > #{afterRecordId} AND c.archived_at IS NULL ORDER BY ci.company_id LIMIT #{memberLimit})
) bounded_members ORDER BY record_type, kind, normalized_value, record_id
